CREATE POLICY "job-outputs members insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'job-outputs' AND EXISTS (SELECT 1 FROM public.workspaces w WHERE w.id::text = (storage.foldername(name))[1] AND public.is_workspace_member(auth.uid(), w.id)));

CREATE POLICY "job-outputs members update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'job-outputs' AND EXISTS (SELECT 1 FROM public.workspaces w WHERE w.id::text = (storage.foldername(name))[1] AND public.is_workspace_member(auth.uid(), w.id)));

CREATE POLICY "job-outputs members delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'job-outputs' AND EXISTS (SELECT 1 FROM public.workspaces w WHERE w.id::text = (storage.foldername(name))[1] AND public.is_workspace_member(auth.uid(), w.id)));